// Log unhandled exception
const handle = global.get('unhandledException');
if(handle) handle(this);

// Check origin of msg execution
if (msg._linkSource) {
    return msg; // Origin: some other flow
} else {
    return null; // Origin: this flow. Stop to prevent 'Missing return' warning
}

// Check if cache can be used or a new call to Data Source is required
const log = global.get('logger');

// Retrieve stored data from flow context
const cachedData = flow.get("cached_dynamic_data");

// Determine cache hit
if (cachedData){
    // Cache HIT
    node.status({ fill: "green", shape: "dot", text: `Cache hit` });
    log(this,`*CACHE HIT* using stored tariff data`);

    // Attach cached data to the message so following nodes can use it
    msg.dynamic = cachedData;

    // Output #1
    return [msg, null];

} else {
    // Cache MISS
    node.status({ fill: "green", shape: "ring", text: `Cache miss }` });

    // Output #2
    return [null, msg];
}

// Clear cache
flow.set("cached_dynamic_data", undefined);
return msg;

// Logger
const log = global.get("logger");

let extraText = 'Power is <b>not</b> applicable for HBC';
if (msg.target === 'Sell') {
    extraText = 'HBC will discharge with <b>max. power</b>';
} else if (msg.target === 'Charge') {
    extraText = 'HBC will charge <b>max. power</b>';
} 
log(this, `HBC Sub-strategy <b>${msg.target}</b> with <b>${msg.power} Watt</b> by Helios (${extraText})`);

// Status
// For example: msg.target = 'Discharge' (in node: 'Set strategy') and msg.power = 500 (in extra node: 'Set Power')
// msg.power is not a HBC field it is just ignored by the 'Home Battery Start' flow.
// Sending target is 'Sell' or 'Charge' works but starts charging or discharging at maximum power
node.status({fill:"green",shape:"dot",text:`${msg.target} with ${msg.power}W`});

// // return msg with solution (directly target the batteries, works but not desired since this is skipping HBC controls):
// let solution_array = [];
// solution_array.push({id:"M1", mode: 'discharge', power: msg.power}); // per battery
